import fitz, docx, json, os

def dump_pdf(path):
    print(f'=== {path} ===')
    doc = fitz.open(path)
    for i, page in enumerate(doc):
        print(f'--- PAGE {i+1} ---')
        print(page.get_text())

def dump_docx(path):
    print(f'=== {path} ===')
    doc = docx.Document(path)
    for p in doc.paragraphs:
        if p.text.strip():
            print(p.text)
    for table in doc.tables:
        for row in table.rows:
            print([cell.text.strip() for cell in row.cells])

