python3 -c "
import ifcopenshell
import ifcopenshell.util.placement

ifc = ifcopenshell.open('/filesystem/final_batch4__structural_task7_roof_deck_design__blind/15_model/DC2-A-STR_Roof_Structure_Model_RevC.ifc')

def get_bbox(el):
    # Get local placement matrix
    m = ifcopenshell.util.placement.get_local_placement(el.ObjectPlacement)
    # Check representation
    rep = el.Representation
    shapes = []
    if rep:
        for item in rep.Representations:
            for it in item.Items:
                if it.is_a('IfcExtrudedAreaSolid'):
                    swept = it.SweptArea
                    depth = it.Depth
                    pos = it.Position
                    # SweptArea can be rectangle or arbitrary closed profile
                    if swept.is_a('IfcRectangleProfileDef'):
                        dx = swept.XDim
                        dy = swept.YDim
                        shapes.append(('rect', dx, dy, depth, pos))
                    elif swept.is_a('IfcArbitraryClosedProfileDef'):
                        shapes.append(('arbitrary', swept.OuterCurve, depth, pos))
    return m, shapes

for el_type in ['IfcOpeningElement', 'IfcBuildingElementProxy', 'IfcWall']:
    for el in ifc.by_type(el_type):
        m, shapes = get_bbox(el)
        pos_ft = (m[0,3]/304.8, m[1,3]/304.8, m[2,3]/304.8)
        print(f'{el.Name} ({el.is_a()}): placement pos_ft={pos_ft}')
        for s in shapes:
            if s[0] == 'rect':
                print(f'   rect: XDim_ft={s[1]/304.8}, YDim_ft={s[2]/304.8}, Depth_ft={s[3]/304.8}')
            elif s[0] == 'arbitrary':
                curve = s[1]
                pts = [(p.Coordinates[0]/304.8, p.Coordinates[1]/304.8) for p in curve.Points]
                print(f'   arbitrary: pts={pts}, Depth_ft={s[2]/304.8}')
"

